const $app = document.getElementById('app');
const $err = document.getElementById('err');
let me = null, domain = '';
const STATUS = { open: '판매중', reserved: '예약중', done: '거래완료' };

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

async function api(path, opts = {}) {
  $err.textContent = '';
  const res = await fetch(path, { headers: { 'Content-Type': 'application/json' }, ...opts, body: opts.body && JSON.stringify(opts.body) });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) { $err.textContent = data.error || '오류가 발생했습니다.'; throw new Error(data.error); }
  return data;
}
const val = (id) => document.getElementById(id).value;

function renderNav() {
  document.getElementById('nav').innerHTML = me
    ? `${esc(me.nickname)} <button onclick="newPost()">글쓰기</button> <button onclick="logout()">로그아웃</button>`
    : '';
}

function showAuth() {
  $app.innerHTML = `
    <h2>로그인</h2>
    <input id="le" placeholder="학교 이메일 (@${esc(domain)})"><input id="lp" type="password" placeholder="비밀번호">
    <button onclick="login()">로그인</button>
    <h2>회원가입</h2>
    <p class="muted">@${esc(domain)} 이메일로만 가입할 수 있습니다.</p>
    <div class="row"><input id="se" placeholder="학교 이메일"><button onclick="requestCode()">인증 코드 받기</button></div>
    <input id="sc" placeholder="인증 코드 6자리"><input id="sn" placeholder="닉네임">
    <input id="sp" type="password" placeholder="비밀번호 (8자 이상)">
    <button onclick="signup()">가입하기</button>`;
}

async function requestCode() { await api('/api/auth/request-code', { method: 'POST', body: { email: val('se') } }); alert('인증 코드를 메일로 보냈습니다.'); }
async function signup() { await api('/api/auth/signup', { method: 'POST', body: { email: val('se'), code: val('sc'), nickname: val('sn'), password: val('sp') } }); await boot(); }
async function login() { await api('/api/auth/login', { method: 'POST', body: { email: val('le'), password: val('lp') } }); await boot(); }
async function logout() { await api('/api/auth/logout', { method: 'POST' }); await boot(); }

async function showList() {
  $app.innerHTML = `
    <div class="row"><input id="q" placeholder="교재명·과목 검색">
    <select id="t" style="width:auto"><option value="">전체</option><option value="sell">팝니다</option><option value="buy">삽니다</option></select>
    <button onclick="loadList()">검색</button></div><div id="list"></div>`;
  await loadList();
}

async function loadList() {
  const { posts } = await api(`/api/posts?q=${encodeURIComponent(val('q'))}&type=${val('t')}`);
  document.getElementById('list').innerHTML = posts.length ? posts.map((p) => `
    <div class="card" onclick="showPost(${p.id})">
      <span class="tag">${p.type === 'sell' ? '팝니다' : '삽니다'}</span><span class="tag">${STATUS[p.status]}</span>
      <b>${esc(p.title)}</b> · ${p.price.toLocaleString()}원
      <div class="muted">${esc(p.course)} · ${esc(p.nickname)} · ${esc(p.created_at)}</div>
    </div>`).join('') : '<p class="muted">글이 없습니다.</p>';
}

async function showPost(id) {
  const { post: p, comments } = await api(`/api/posts/${id}`);
  $app.innerHTML = `
    <button onclick="showList()">← 목록</button>
    <h2>${esc(p.title)}</h2>
    <p><span class="tag">${p.type === 'sell' ? '팝니다' : '삽니다'}</span><span class="tag">${STATUS[p.status]}</span>
      ${p.price.toLocaleString()}원 · 상태: ${esc(p.condition) || '-'}</p>
    <p class="muted">과목: ${esc(p.course) || '-'} · ${esc(p.nickname)} · ${esc(p.created_at)}</p>
    <p style="white-space:pre-wrap">${esc(p.body)}</p>
    ${p.mine ? `<button onclick="editPost(${p.id})">수정</button> <button onclick="deletePost(${p.id})">삭제</button>` : ''}
    <h3>댓글</h3>
    ${comments.map((c) => `<p><b>${esc(c.nickname)}</b> ${esc(c.body)} <span class="muted">${esc(c.created_at)}</span></p>`).join('')}
    <textarea id="cb" placeholder="거래 문의를 남기세요"></textarea>
    <button onclick="addComment(${p.id})">댓글 등록</button>`;
}

async function addComment(id) { await api(`/api/posts/${id}/comments`, { method: 'POST', body: { body: val('cb') } }); showPost(id); }
async function deletePost(id) { if (confirm('삭제할까요?')) { await api(`/api/posts/${id}`, { method: 'DELETE' }); showList(); } }

function postForm(p = {}) {
  $app.innerHTML = `
    <h2>${p.id ? '글 수정' : '글쓰기'}</h2>
    <select id="ft"><option value="sell">팝니다</option><option value="buy">삽니다</option></select>
    <input id="fti" placeholder="교재명" value="${esc(p.title)}">
    <input id="fc" placeholder="과목명 / 교수명" value="${esc(p.course)}">
    <input id="fp" type="number" min="0" placeholder="가격(원)" value="${esc(p.price)}">
    <select id="fco"><option>새 책</option><option>깨끗함</option><option>필기 있음</option><option>많이 낡음</option></select>
    ${p.id ? `<select id="fs"><option value="open">판매중</option><option value="reserved">예약중</option><option value="done">거래완료</option></select>` : ''}
    <textarea id="fb" rows="6" placeholder="설명 (거래 장소, 연락 방법 등)">${esc(p.body)}</textarea>
    <button onclick="savePost(${p.id || 0})">저장</button> <button onclick="showList()">취소</button>`;
  if (p.type) document.getElementById('ft').value = p.type;
  if (p.condition) document.getElementById('fco').value = p.condition;
  if (p.status) document.getElementById('fs').value = p.status;
}

function newPost() { postForm(); }
async function editPost(id) { const { post } = await api(`/api/posts/${id}`); postForm(post); }

async function savePost(id) {
  const body = { type: val('ft'), title: val('fti'), course: val('fc'), price: Number(val('fp')), condition: val('fco'), body: val('fb') };
  if (id) { body.status = val('fs'); await api(`/api/posts/${id}`, { method: 'PUT', body }); showPost(id); }
  else { const r = await api('/api/posts', { method: 'POST', body }); showPost(r.id); }
}

async function boot() {
  domain = (await api('/api/config')).domain;
  me = (await api('/api/me')).user;
  renderNav();
  me ? showList() : showAuth();
}
boot();

