    <textarea id="fb" rows="6" placeholder="설명 (거래 장소, 연락 방법 등)">${esc(p.body)}</textarea>
    <button onclick="savePost(${p.id || 0})">저장</button> <button onclick="showList()">취소</button>`;
  if (p.type) document.getElementById('ft').value = p.type;
  if (p.condition) document.getElementById('fco').value = p.condition;
  if (p.status) document.getElementById('fs').value = p.status;
}

function newPost() { postForm(); }
async function editPost(id) { const { post } = await api(`/api/posts/${id}`); postForm(post); }

async function savePost(id) {
  const body = { type: val('ft'), title: val('fti'), course: val('fc'), price: Number(val('fp')), condition: val('fco'), body: val('fb') };
  if (id) { body.status = val('fs'); await api(`/api/posts/${id}`, { method: 'PUT', body }); showPost(id); }
